def dsa_sign(m, x, p, q, g):
    while True:
        k = random_int(1, q - 1)  # 서명마다 새 비밀 난수
        r = pow(g, k, p) % q
        s = inv(k, q) * (H(m) + x * r) % q
        if r != 0 and s != 0:
            return r, s

def dsa_verify(m, r, s, y, p, q, g):
    if not (0 < r < q and 0 < s < q):
        return False
    w = inv(s, q)
    u1 = H(m) * w % q
    u2 = r * w % q
    v = pow(g, u1, p) * pow(y, u2, p) % p % q
    return v == r
# k를 재사용하면 두 서명으로 x를 풀 수 있음
